/* @lc app=leetcode id=2381 lang=kotlin */ class Solution { fun shiftingLetters(s: String, shifts: Array<IntArray>): String = IntArray(s.length + 1).apply { shifts.forEach { (st, ed, dr) -> if (dr == 1) st.also { this[st] = this[st] + 1 }.also { this[ed + 1] = this[ed + 1] - 1 } else st.also { this[st] = this[st] - 1 }.also { this[ed + 1] = this[ed + 1] + 1 } } }.let { diff -> s.indices.fold(0 to CharArray(s.length)) { (sum, arr), i -> (sum + diff[i]).let { ns -> (ns % 26).let { m -> ((s[i] - 'a' + m) % 26).let { r -> arr.apply { this[i] = 'a' + (if (r < 0) r + 26 else r) }.run { ns to arr } } } } }.second.let { String(it) } } }